// @generated by:gauntlet run:godseye-e08-independent-gauntlet
import { randomUUID } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  type E08ObservabilityFixture,
  e08ObservabilityFixture,
} from "./helpers/e08-observability.js";

describe("E08 retention separates durable health from expired log content", () => {
  let f: E08ObservabilityFixture;
  beforeEach(async () => {
    f = await e08ObservabilityFixture();
  });
  afterEach(async () => {
    await f.store.close();
  });
  it("T-AC-809 removes every expired log while retaining only stale minimal source health and longer metric history", async () => {
    const source = await f.register();
    await f.engine.ingest(
      f.service,
      source.id,
      f.event({ code: "RETENTION_CANARY", metrics: [{ name: "request.count", value: 1 }] }),
      randomUUID(),
    );
    f.clock.advance(8 * 86400000);
    await f.engine.prune(f.freshOwner());
    expect((await f.engine.logs(f.freshOwner(), {})).records).toHaveLength(0);
    expect(
      (await f.engine.health(f.freshOwner())).sources.find((row) => row.source.id === source.id),
    ).toMatchObject({ freshness: "stale", observedState: "healthy" });
    const metrics = await f.engine.metrics(f.freshOwner());
    expect(metrics.records).toHaveLength(1);
    expect(JSON.stringify(metrics)).not.toContain("RETENTION_CANARY");
    f.clock.advance(23 * 86400000);
    await f.engine.prune(f.freshOwner());
    expect((await f.engine.metrics(f.freshOwner())).records).toHaveLength(0);
    expect(
      (await f.engine.health(f.freshOwner())).sources.find((row) => row.source.id === source.id),
    ).toMatchObject({ freshness: "stale" });
  });
  it("T-AC-812 healthy accounting detector cannot clear a stale accounting condition owned by telemetry", async () => {
    const source = await f.register();
    await f.engine.ingest(
      f.service,
      source.id,
      f.event({ state: "unknown", event: "accounting.unknown", code: "MODEL_ACCOUNTING_UNKNOWN" }),
      randomUUID(),
    );
    const original = (
      await f.infrastructure.incidents.evaluate(f.freshOwner(), randomUUID())
    ).incidents.find((row) => row.kind === "accounting");
    expect(original).toBeDefined();
    f.clock.advance(5001);
    const later = (
      await f.infrastructure.incidents.evaluate(f.freshOwner(), randomUUID())
    ).incidents.find((row) => row.id === original?.id);
    expect(later).toMatchObject({ state: "open", resolution: null });
  });
  it("T-AC-812 healthy archive detector cannot clear a stale archive condition owned by telemetry", async () => {
    const source = await f.register();
    await f.engine.ingest(
      f.service,
      source.id,
      f.event({ state: "degraded", event: "archive.stale", code: "SOURCE_ARCHIVE_LAG" }),
      randomUUID(),
    );
    const original = (
      await f.infrastructure.incidents.evaluate(f.freshOwner(), randomUUID())
    ).incidents.find((row) => row.key === `telemetry:archive-lag:${source.id}`);
    expect(original).toBeDefined();
    f.clock.advance(5001);
    const later = (
      await f.infrastructure.incidents.evaluate(f.freshOwner(), randomUUID())
    ).incidents.find((row) => row.id === original?.id);
    expect(later).toMatchObject({ state: "open", resolution: null });
  });
});
